import{_ as e,o as i,c as t,a2 as a}from"./chunks/framework.BXA5Pi9t.js";const _=JSON.parse('{"title":"Ceph Developer Summit Quincy: CephFS","description":"","frontmatter":{"title":"Ceph Developer Summit Quincy: CephFS","date":"2021-04-12T00:00:00.000Z","updated":"2021-04-13T00:00:00.000Z","tags":["CephFS","CephDeveloperSummit","分布式存储","CephFS开发","Ceph性能"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Developer_Summit_Quincy_-_CephFS.md","filePath":"posts/2021/Ceph_Developer_Summit_Quincy_-_CephFS.md","lastUpdated":1780459816000}'),r={name:"posts/2021/Ceph_Developer_Summit_Quincy_-_CephFS.md"};function o(p,l,n,s,u,h){return i(),t("div",null,[...l[0]||(l[0]=[a('<h2 id="改进后的中文总结内容" tabindex="-1">改进后的中文总结内容 <a class="header-anchor" href="#改进后的中文总结内容" aria-label="Permalink to &quot;改进后的中文总结内容&quot;">​</a></h2><p>本次会议主要围绕CephFS的多个关键议题展开讨论，包括Dashboard和NFS的当前状态与后续步骤、MDS内存目标、文件系统加密（fs-crypt）、异步操作、递归删除、MDS滚动升级、文件系统镜像指标以及客户端隔离（fencing）等。</p><h3 id="讨论的主要议题" tabindex="-1">讨论的主要议题 <a class="header-anchor" href="#讨论的主要议题" aria-label="Permalink to &quot;讨论的主要议题&quot;">​</a></h3><ol><li><p><strong>Dashboard和NFS的当前状态与后续步骤</strong></p><ul><li>讨论了Dashboard中文件系统特定组件的界面，包括默认系统、MDS信息、客户端连接、目录列表和快照创建等功能。</li><li>讨论了NFS v3的支持问题，决定未来不再支持NFS v3，并可能在未来版本中移除相关支持。</li><li>提到了NFS插件的集成工作，以及与Ganesha的兼容性问题。</li></ul></li><li><p><strong>MDS内存目标</strong></p><ul><li>讨论了动态调整MDS缓存内存限制的PR，目标是根据MDS的总内存使用情况动态修改缓存限制。</li></ul></li><li><p><strong>文件系统加密（fs-crypt）</strong></p><ul><li>讨论了文件名加密的实现进展，以及内容加密中遇到的截断问题。</li><li>提到了客户端处理未缓存I/O时的加密需求，以及可能的解决方案。</li></ul></li><li><p><strong>异步操作</strong></p><ul><li>讨论了异步创建和删除操作的实现，以及如何处理递归操作中的同步问题。</li></ul></li><li><p><strong>递归删除</strong></p><ul><li>提出了添加递归删除RPC的建议，以简化管理操作，特别是针对子卷的删除。</li><li>讨论了实现细节和潜在的挑战，如硬链接的处理。</li></ul></li><li><p><strong>MDS滚动升级</strong></p><ul><li>讨论了简化MDS升级过程的方案，包括避免MDS在兼容性设置变化时自杀的问题。</li><li>提出了支持混合版本MDS的长期目标。</li></ul></li><li><p><strong>文件系统镜像指标</strong></p><ul><li>讨论了与RBD镜像指标对齐的需求，以便更好地监控和管理镜像过程。</li></ul></li><li><p><strong>客户端隔离（fencing）</strong></p><ul><li>讨论了在Kubernetes集群中实现客户端隔离的需求，以便在集群不可用时能够安全地隔离客户端。</li><li>提出了基于标签和生成ID的解决方案，但尚未确定最终方案。</li></ul></li></ol><h3 id="决定的事项" tabindex="-1">决定的事项 <a class="header-anchor" href="#决定的事项" aria-label="Permalink to &quot;决定的事项&quot;">​</a></h3><ul><li>未来版本中将不再支持NFS v3。</li><li>将探索简化MDS升级过程的方法，并考虑支持混合版本MDS。</li><li>将研究递归删除RPC的实现细节和挑战。</li></ul><h3 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h3><ul><li>继续推进文件系统加密的开发，解决截断问题。</li><li>研究并实现递归删除RPC，考虑硬链接的处理。</li><li>完善MDS滚动升级方案，确保升级过程的稳定性和安全性。</li><li>跟进文件系统镜像指标的开发，确保与RBD镜像指标的一致性。</li><li>进一步讨论和确定客户端隔离的最终方案。</li></ul><p>本次会议为CephFS的持续改进和发展提供了重要的讨论和决策基础，后续的工作将围绕这些关键议题展开。</p>',9)])])}const c=e(r,[["render",o]]);export{_ as __pageData,c as default};
